\begin{document}

\title[The Two-Adic Price Law]{The Two-Adic Price Law:\\ Exactly Two Clicks of Visibility, Then Structural Sealing}

\author{Aristotle}
\date{24 August 2026}

\begin{abstract}
The Price tree is a ternary tree on Euclid parameter pairs $(m,n)$, rooted at $(2,1)$, whose
three moves $A:(m,n)\mapsto(m+n,2n)$, $B:(m,n)\mapsto(2m,m-n)$, $C:(m,n)\mapsto(2m,m+n)$
enumerate every primitive Pythagorean triple exactly once. Each node therefore carries a
unique address, a word over $\{A,B,C\}$, and each node with odd leg $N=m^2-n^2$ is exactly a
coprime factorisation $N=pq$ with $p=m-n$, $q=m+n$. We determine, exactly and in both
directions, how much of the address is a function of the $2$-adic data of $N$.

Reading the address backwards from the leaf, positions $0$ and $1$ are visible: the letter at
position $0$ is $A$ iff $N\equiv1\pmod4$, and the letter at position $1$ is $A$ iff
$N\bmod 8\in\{1,3\}$; the resulting map from $N\bmod 8\in\{1,3,5,7\}$ to the pair of
$A$-nesses is a bijection, and all four values are attained. Positions $2$ and beyond are
invisible: for every $t\ge2$ there exist pairs of valid nodes with identical odd legs whose
addresses agree in $A$-ness at all positions below $t$ and disagree at $t$. Consequently no
function of $N$ whatsoever---hence no residue $N\bmod2^k$, at any $2$-adic depth $k$---computes
the $A$-ness at any position $t\ge2$. The failure is generic (infinitely many odd legs carry a
splitting pair at each position, so no eventually correct classifier exists) and it survives
the addition of the node's depth as free side information.

The mechanism behind both halves is a pair of exact run laws in the odd-pair coordinates
$U=p+q=2m$, $V=q-p=2n$: an $A$-step halves $V$ and occurs iff $\vtwo(U)=1$; a $B$- or $C$-step
halves $U$ and occurs iff $\vtwo(U)\ge2$. Hence non-$A$ steps decrement $\vtwo(U)$ by one and
the first $A$ of the address sits at position $\vtwo(U)-1$; the residue $N\bmod 2^k$ resolves
$\vtwo(U)$ only up to the trichotomy $\{1,2,\ge3\}$. The $B$-versus-$C$ decision is not a
congruence at all but the size comparison $q<3p$, invisible to every residue.
Information-theoretically, the mutual information between $N\bmod2^k$ and the pair of youngest
letters saturates exactly at modulus $8$.
\end{abstract}

\maketitle

\section{Introduction}

\subsection{Trees of Pythagorean triples}
A \emph{primitive Pythagorean triple} is a triple $(a,b,c)$ of positive integers with
$a^2+b^2=c^2$ and $\gcd(a,b,c)=1$. Euclid's parametrisation is a bijection between such
triples (with $a$ odd) and \emph{Euclid pairs}: pairs $(m,n)$ of coprime integers with
$m>n>0$ of opposite parity, via
\[
 a=m^2-n^2,\qquad b=2mn,\qquad c=m^2+n^2 .
\]
We call $a=N=m^2-n^2$ the \emph{odd leg}.

Several ternary trees organise the primitive triples. The classical one, due to Berggren, acts
by three integer matrices on the triple itself. The Price tree acts instead on the Euclid
pair. Its root is $(2,1)$---the triple $(3,4,5)$---and its three moves are
\[
 A:(m,n)\mapsto(m+n,2n),\qquad B:(m,n)\mapsto(2m,m-n),\qquad C:(m,n)\mapsto(2m,m+n).
\]
Every Euclid pair is reached from the root by exactly one word over $\{A,B,C\}$; that word is
the node's \emph{address}.

\subsection{The question}
The odd leg factors as
\[
 N=m^2-n^2=(m-n)(m+n)=pq ,
\]
with $p=m-n$, $q=m+n$ odd, positive and coprime; conversely every coprime factorisation
$N=pq$ with $0<p<q$ recovers $m=(p+q)/2$, $n=(q-p)/2$. Thus the nodes with a given odd leg $N$
are in bijection with the coprime factorisations of $N$, which makes the address a
factorisation-sensitive statistic. If a cheap arithmetic function of $N$---a residue
$N\bmod2^k$, say---determined a growing prefix of the address, it would be leaking
multiplicative information about $N$ from purely additive data. Empirically two letters are
readable; the content of this paper is that two is an exact ceiling.

Throughout, positions in an address are counted \emph{backwards from the leaf}: position $0$ is
the last letter, position $1$ the second-to-last, and so on. This is the natural indexing,
because the moves are inverted from the leaf upward and the arithmetic of the descent is local
to the leaf.

\subsection{Results}
Write $\ell_t(P)$ for the letter of the node $P$ at position $t$, defined whenever the address
of $P$ has more than $t$ letters, and $\vtwo$ for the $2$-adic valuation.

\emph{Visibility (two clicks).} $\ell_0(P)=A$ iff $N\equiv1\pmod4$; $\ell_1(P)=A$ iff
$N\bmod8\in\{1,3\}$; the map $N\bmod8\mapsto([\ell_0=A],[\ell_1=A])$ is a bijection
$\{1,3,5,7\}\to\{\Ttrue,\Tfalse\}^2$ and all four values occur.

\emph{Sealing (nothing else).} For every $t\ge2$ there are valid nodes $P\ne Q$ of depth $>t$
with equal odd legs, agreeing in $A$-ness below $t$ and disagreeing at $t$; hence no function
of $N$, and no function of $N\bmod2^k$ for any $k$, reads position $t$. Infinitely many odd
legs carry such a pair, so no eventually correct classifier exists; and there are
\emph{equal-depth} such pairs at every $t\ge2$, so no function of $(N,\text{depth})$ works
either.

\emph{Mechanism.} The $A$-run law, the non-$A$-run law and the first-$A$ law
(Section~\ref{sec:mech}), together with the size rule separating $B$ from $C$.

\section{Definitions and basic facts}

\begin{definition}[Valid pair]
A pair $(m,n)$ of natural numbers is \emph{valid} if $0<n<m$, $\gcd(m,n)=1$ and $m+n$ is odd.
The \emph{root} is $(2,1)$.
\end{definition}

\begin{definition}[Letters and parent]
Each of $A,B,C$ is injective on valid pairs, and their images partition the non-root valid
pairs. Hence every non-root valid pair has a unique letter
\[
 \lett(m,n)=\begin{cases} A & n\ \text{even},\\ B & n\ \text{odd},\ 2n<m,\\ C & n\ \text{odd},\ 2n>m,\end{cases}
\]
(the case $2n=m$ does not occur) and a unique parent
\[
 \pi(m,n)=\begin{cases}(m-n/2,\ n/2) & n\ \text{even},\\ (m/2,\ m/2-n) & n\ \text{odd},\ 2n<m,\\ (m/2,\ n-m/2) & n\ \text{odd},\ 2n>m.\end{cases}
\]
\end{definition}

\begin{definition}[Address, depth, position]
The \emph{address} $\adr(P)$ is the word
$\lett(\pi^{d-1}P)\cdots\lett(\pi P)\,\lett(P)$, where $d$ is least with $\pi^dP=(2,1)$; the
\emph{depth} is $d=|\adr(P)|$. The letter at position $t$ is $\ell_t(P)=\lett(\pi^tP)$, which is
the $t$-th entry of the reversed address whenever $t<|\adr(P)|$.
\end{definition}

\begin{definition}[Odd leg and odd-pair coordinates]
$N(m,n)=m^2-n^2$; $p=m-n$, $q=m+n$, so $N=pq$; and
$U=p+q=2m$, $V=q-p=2n$.
\end{definition}

\begin{lemma}[Parity and residues]\label{lem:parity}
For a valid pair exactly one of $m,n$ is even, and
\[
 N\bmod 8=\begin{cases}1 & 4\mid n,\\ 5 & n\equiv2\ (4),\\ 3 & n\ \text{odd},\ m\equiv2\ (4),\\ 7 & n\ \text{odd},\ 4\mid m.\end{cases}
\]
In particular $N\equiv1\pmod4$ iff $n$ is even.
\end{lemma}

\begin{proof}[Proof sketch]
Squares of odd numbers are $1$ modulo $8$; $n\equiv2\pmod4$ gives $n^2\equiv4\pmod{32}$, and
$4\mid n$ gives $16\mid n^2$. Substitute in $N=m^2-n^2$ and reduce modulo $8$.
\end{proof}

\begin{lemma}[Depth lower bound]\label{lem:depth}
If the first $L$ iterated parents of a valid $P$ differ from the root, then $|\adr(P)|\ge L$.
Since $m+n\le3^{\,|\adr(P)|+1}$ for every valid pair, any node with $m+n>27$ has depth at
least $3$.
\end{lemma}

\section{The run mechanism}\label{sec:mech}

\begin{lemma}[Closed form along an $A$-run]\label{lem:Aiterate}
If $n\le m$ and $2^t\mid n$ then
$\pi^t(m,n)=\bigl(m-n+n/2^t,\ n/2^t\bigr)$.
\end{lemma}

\begin{proof}[Proof sketch]
Induction on $t$; at each stage the second coordinate $n/2^t$ is even, so the parent rule for
even second coordinate applies and halves it again.
\end{proof}

\begin{theorem}[$A$-run law]\label{thm:Arun}
Let $(m,n)$ be valid with $n\le m$ and $2^t\mid n$. Then $\ell_t(m,n)=A$ iff $2^{t+1}\mid n$.
Consequently, if $n$ is even with $\vtwo(n)=k$, the address begins (from the leaf) with exactly
$k$ letters $A$, followed by a non-$A$.
\end{theorem}

\begin{proof}[Proof sketch]
By Lemma~\ref{lem:Aiterate} the $t$-th ancestor has second coordinate $n/2^t$, whose letter is
$A$ precisely when that coordinate is even.
\end{proof}

\begin{lemma}[One step at an odd node]\label{lem:oddstep}
If $n$ is odd then $\pi(m,n)=(m/2,\ |m/2-n|)$: the first coordinate is exactly halved.
\end{lemma}

\begin{theorem}[Non-$A$-run law]\label{thm:nonArun}
Let $n$ be odd with $0<n<m$ and $2^{t+1}\mid m$. Then $\ell_t(m,n)\ne A$; and if moreover
$2^{t+2}\nmid m$ then $\ell_{t+1}(m,n)=A$.
\end{theorem}

\begin{proof}[Proof sketch]
Induction on $t$. For $t=0$, $n$ odd gives $\ell_0\ne A$; if $m\equiv2\pmod4$ then the parent
$(m/2,|m/2-n|)$ has even second coordinate, since $m/2$ and $n$ are both odd, so its letter is
$A$. For the step, $4\mid m$ forces the parent $(m/2,d)$ to have $d$ odd, $d<m/2$ and
$2^{t+1}\mid m/2$; apply the hypothesis to the parent and use $\ell_{t+1}(P)=\ell_t(\pi P)$.
\end{proof}

\begin{theorem}[First-$A$ law]\label{thm:firstA}
Let $(m,n)$ be valid with $n$ odd, hence $m$ even, and $k=\vtwo(m)$. Then $\ell_k(m,n)=A$ and
$\ell_t(m,n)\ne A$ for every $t<k$. Equivalently, with $U=p+q=2m$ and $u_0=\vtwo(U)\ge2$, the
first $A$ of the address sits exactly at position $u_0-1$.
\end{theorem}

\begin{theorem}[Leading-run dichotomy]
For every valid $(m,n)$ exactly one of the following holds: $n$ is even and the address ends,
read from the leaf, with exactly $\vtwo(n)$ letters $A$ followed by a non-$A$; or $n$ is odd and
it ends with exactly $\vtwo(m)$ non-$A$ letters followed by an $A$.
\end{theorem}

\subsection{Valuation bookkeeping}
Theorems~\ref{thm:Arun} and~\ref{thm:firstA} are exactly the following statement. Every ascent
step halves exactly one of $U=p+q$ and $V=q-p$: an $A$-step halves $V$ and occurs iff
$\vtwo(U)=1$; a $B$- or $C$-step halves $U$ and occurs iff $\vtwo(U)\ge2$. Hence a non-$A$ step
decrements $\vtwo(U)$ by one and the first $A$ appears when the countdown reaches $1$. For the
node $(41,14)$, whose address is $ABBABA$:

\begin{center}
\begin{tabular}{cccc}
\toprule
position & letter & $\vtwo(U)$ & $\vtwo(V)$\\
\midrule
$0$ & $A$ & $1$ & $2$\\
$1$ & $B$ & $2$ & $1$\\
$2$ & $A$ & $1$ & $2$\\
$3$ & $B$ & $3$ & $1$\\
$4$ & $B$ & $2$ & $1$\\
$5$ & $A$ & $1$ & $2$\\
\bottomrule
\end{tabular}
\end{center}

\begin{theorem}[$B$/$C$ is a size rule]\label{thm:BC}
For a valid pair, with $p=m-n$ and $q=m+n$,
\[
 \lett(m,n)=B \iff \bigl(N\equiv3\!\!\pmod4\ \text{ and }\ q<3p\bigr).
\]
\end{theorem}

\begin{proof}[Proof sketch]
$N\equiv3\pmod 4$ is equivalent to $n$ odd, i.e.\ to the letter being $B$ or $C$; within that
case the letter is $B$ iff $2n<m$, and $2n<m\iff q-p<\frac{p+q}{2}\iff q<3p$.
\end{proof}

The second condition is a pure size comparison between the two factors of $N$, hence invisible
to every residue of $N$. It also explains the relative rarity of $B$ in samples where the
congruence and the inequality decouple: $\Pr(B)$ is the probability of the size event $q<3p$
cut in half by a congruence of probability one half.

\section{The two visible clicks}

\begin{theorem}[Position $0$]\label{thm:pos0}
For every valid $P$: $\ell_0(P)=A$ iff $N(P)\equiv1\pmod4$.
\end{theorem}

\begin{theorem}[Position $1$]\label{thm:pos1}
For every valid $P$: $\ell_1(P)=A$ iff $N(P)\bmod8\in\{1,3\}$.
\end{theorem}

\begin{proof}[Proof sketch]
If $n$ is even then by Theorem~\ref{thm:Arun} $\ell_1=A$ iff $4\mid n$, i.e.\ $N\equiv1\pmod8$
by Lemma~\ref{lem:parity}. If $n$ is odd then by Theorem~\ref{thm:nonArun} $\ell_1=A$ iff
$m\equiv2\pmod4$, i.e.\ $N\equiv3\pmod8$.
\end{proof}

\begin{theorem}[Bijection with $N\bmod 8$]\label{thm:bijection}
For every valid $P$,
\[
\begin{aligned}
 N\equiv1\ (8)&\iff(\ell_0=A,\ \ell_1=A), &\quad N\equiv5\ (8)&\iff(\ell_0=A,\ \ell_1\ne A),\\
 N\equiv3\ (8)&\iff(\ell_0\ne A,\ \ell_1=A), &\quad N\equiv7\ (8)&\iff(\ell_0\ne A,\ \ell_1\ne A).
\end{aligned}
\]
All four patterns are attained by nodes of depth at least $3$, for instance $(17,16)$,
$(26,3)$, $(27,2)$, $(28,3)$. Hence the two youngest $A$-nesses and $N\bmod8$ determine one
another.
\end{theorem}

\begin{theorem}[Closed form at position $2$]\label{thm:pos2}
For a valid non-root $(m,n)$, $\ell_2(m,n)=A$ if and only if
\[
\begin{cases}
 8\mid n & \text{if } 4\mid n,\\
 m-n/2\equiv2\ (4) & \text{if } n\equiv2\ (4),\\
 m/2\equiv n\ (4) & \text{if $n$ odd and } m\equiv2\ (4),\\
 m\equiv4\ (8) & \text{if $n$ odd and } 4\mid m.
\end{cases}
\]
\end{theorem}

The criterion of Theorem~\ref{thm:pos2} is a condition on the \emph{node} modulo $16$, not on
$N$. The remaining sections show that this is unavoidable.

\section{Death at position two}

\begin{definition}
For $y\in\mathbb{N}$ put $X(y)=(3y+5,\ 3y+4)$ and $Y(y)=(y+3,\ y)$.
\end{definition}

\begin{lemma}
$X(y)$ is valid for $y>0$, and $Y(y)$ is valid for $y>0$ with $3\nmid y$; both have odd leg
$6y+9$. They are the coprime factorisations $N=1\cdot N$ and $N=3\cdot\frac{N}{3}$ of the same
odd number.
\end{lemma}

\begin{theorem}[The twins split position $2$]\label{thm:twins}
For $y\ge9$ with $3\nmid y$, $\ [\ell_2(X(y))=A]\ne[\ell_2(Y(y))=A]$.
\end{theorem}

\begin{proof}[Proof sketch]
Both nodes are valid and non-root, so Theorem~\ref{thm:pos2} applies. Substituting the two
parametrisations turns the four-case criterion into a statement about $y$ modulo $16$, and in
each resulting case exactly one of the two criteria holds.
\end{proof}

Sharing the odd leg, the twins agree at positions $0$ and $1$ by
Theorems~\ref{thm:pos0}--\ref{thm:pos1}: they agree exactly where the residue can see, and
disagree at the first position where it cannot. The smallest instance is $N=33$, realised by
$(7,4)$ with address $BAA$ and $(17,16)$ with address $AAAA$.

\begin{lemma}[Hitting an arbitrary class arbitrarily far out]\label{lem:hit}
For all $k$, all $M$, and every odd $r$, there is $y>M$ with $3\nmid y$ and
$6y+9\equiv r\pmod{2^k}$.
\end{lemma}

\begin{proof}[Proof sketch]
Since $3$ is invertible modulo every power of two (an easy induction produces $u,s$ with
$3u=1+2^ks$), solve $3w\equiv r\pmod{2^{k+1}}$ with $w$ odd and large, write $w=2y_0+3$ and
note $6y_0+9=3w$. If $3\mid y_0$, replace $y_0$ by $y_0+2^k$: this preserves the congruence
modulo $2^k$ and changes $y_0$ modulo $3$, because $2^k\not\equiv0\pmod3$.
\end{proof}

\begin{theorem}[Every $2$-adic cell is split]\label{thm:cellsplit}
For every $k$ and every odd $r$ there are valid nodes $P,Q$ of depth at least $3$ with
$N(P)=N(Q)\equiv r\pmod{2^k}$, with equal $A$-nesses at positions $0$ and $1$, and with
opposite $A$-nesses at position $2$.
\end{theorem}

\begin{theorem}[No odd-leg classifier at position two]\label{thm:noclass2}
For every $f:\mathbb{N}\to\{\Ttrue,\Tfalse\}$ it is false that $\ell_2(P)=A\iff f(N(P))$ for all
valid $P$ of depth at least $3$. A fortiori, for every $k$ the rule
$\ell_2=A\iff f(N\bmod2^k)$ fails.
\end{theorem}

\begin{corollary}[Zero conditional determinacy]\label{cor:zerovar}
For every node $P$ and every $k$, the $2$-adic cell of $P$ contains two nodes with opposite
$A$-nesses at position $2$: the conditional law of the third letter given the whole $2$-adic
residue is never degenerate, at any depth of the filtration.
\end{corollary}

\begin{theorem}[Capacity exactly two]
For every $k$ and odd $r$: inside the cell $\{N\equiv r \bmod 2^{k+3}\}$ the $A$-nesses at
positions $0$ and $1$ are constant---they are read off $r\bmod 8$---while the $A$-ness at
position $2$ still takes both values. Refining the modulus past $8$ adds no information about
the address.
\end{theorem}

\section{Sealing at every position}

\begin{definition}\label{def:bigfam}
For $s\ge0$ put $t=s+2$, $W_s=10\cdot2^s-3$ (odd, $\ge7$) and
\[
 X_s=\bigl(2^tW_s+1,\ 2^tW_s\bigr),\qquad Y_s=\bigl(12\cdot2^s-1,\ 2^{t+1}\bigr).
\]
\end{definition}

\begin{lemma}
$X_s$ and $Y_s$ are valid, both of depth greater than $t$, and
\[
 N(X_s)=N(Y_s)=2^{t+1}W_s+1=80\cdot4^s-24\cdot2^s+1 ,
\]
the sequence beginning $57,273,1185,4929,20097,81153,\dots$ Moreover
$\vtwo\bigl((X_s)_2\bigr)=t$ exactly and $2^{t+1}\mid (Y_s)_2$.
\end{lemma}

\begin{theorem}[Splitting at position $t$]\label{thm:bigsplit}
For all $u<t$ one has $\ell_u(X_s)=\ell_u(Y_s)=A$, while $\ell_t(X_s)\ne A$ and
$\ell_t(Y_s)=A$.
\end{theorem}

\begin{proof}[Proof sketch]
Theorem~\ref{thm:Arun} applied to both nodes: for $u<t$ the power $2^{u+1}$ divides both second
coordinates, giving $A$; at $u=t$ it divides $2^{t+1}$ but not $2^tW_s$, since $W_s$ is odd.
\end{proof}

\begin{theorem}[Sealing at all positions]\label{thm:sealall}
For every $t\ge2$ and every $f:\mathbb{N}\to\{\Ttrue,\Tfalse\}$ the rule $\ell_t(P)=A\iff f(N(P))$
fails at some valid node of depth greater than $t$; consequently no rule
$\ell_t=A\iff f(N\bmod2^k)$ is correct, for any $k$.
\end{theorem}

Together with Theorems~\ref{thm:pos0}--\ref{thm:bijection} this is the \emph{Two-Adic Price
Law}: the $2$-adic reading of a Price address has exactly two clicks, $N\bmod4$ and $N\bmod8$,
and is structurally blind from position $2$ onwards.

\section{Sealing is generic, not sporadic}

\begin{definition}
For $s,v\ge0$ set $K_{s,v}=2^{s+1}(4v^2+12v+5)+(2v+3)$ (odd, $\ge13$),
\[
 \mathcal{X}_{s,v}=\bigl(2^{s+2}K_{s,v}+1,\ 2^{s+2}K_{s,v}\bigr),\qquad
 \mathcal{Y}_{s,v}=\bigl(2^{s+2}(2v+3)+1,\ 2^{s+3}\bigr),
\]
with common odd leg $\mathcal{N}_{s,v}=2^{s+3}K_{s,v}+1$.
\end{definition}

\begin{lemma}[Two reusable tools]\label{lem:tools}
\begin{enumerate}
\item \emph{Depth from a valuation.} A valid $(m,n)$ with $2^L\mid n$ and $n/2^L\ge2$ has depth
at least $L+1$.
\item \emph{Splitting from a valuation gap.} If $P,Q$ are valid with $\vtwo(P_2)=t$ exactly and
$2^{t+1}\mid Q_2$, then $\ell_u(P)=\ell_u(Q)=A$ for all $u<t$ and
$[\ell_t(P)=A]\ne[\ell_t(Q)=A]$.
\end{enumerate}
\end{lemma}

\begin{theorem}[Infinitely many splitting odd legs at each position]\label{thm:generic}
For every $t=s+2\ge2$ the numbers $\mathcal{N}_{s,v}$, $v\ge0$, are pairwise distinct and each
carries a pair of valid nodes of depth greater than $t$ agreeing in $A$-ness below $t$ and
disagreeing at $t$. Hence the set of odd legs carrying a splitting pair at position $t$ is
infinite.
\end{theorem}

\begin{corollary}[No eventually correct classifier]
For every $t\ge2$, every bound $B$ and every $f$, the rule $\ell_t=A\iff f(N)$ fails at some
valid node whose odd leg exceeds $B$; likewise for $f(N\bmod2^k)$, for every $k$.
\end{corollary}

\section{The depth is not the missing bit}

The depth is genuinely extra information: it is not a function of $N$. It does not help. The
proof is cleanest when the two nodes are specified \emph{by their addresses}, which makes their
depths equal by construction.

\begin{definition}
For $t\ge3$ consider the two words of common length $2t$,
\[
 \mathcal{W}^X_t=A^{\,t-1}BA^{\,t},\qquad \mathcal{W}^Y_t=CA^{\,t-3}CA^{\,t+1}.
\]
\end{definition}

\begin{lemma}[Evaluation]
Following these words from the root yields
\[
 \mathcal{X}^d_t=\bigl(2^{t+1}+1,\ 2^t\bigr),\qquad
 \mathcal{Y}^d_t=(M_t+1,\ M_t),\quad M_t=2^{t+1}\bigl(3\cdot2^{t-2}+1\bigr),
\]
and both have odd leg $\mathcal{N}^d_t=2M_t+1=3\cdot2^{2t}+2^{t+2}+1$.
\end{lemma}

\begin{proof}[Proof sketch]
Iterating $A$ has the closed form $A^k(m,n)=\bigl(m+(2^k-1)n,\ 2^kn\bigr)$, which reduces both
evaluations to a short computation; the odd leg of $\mathcal{X}^d_t$ is
$(2^{t+1}+1)^2-(2^t)^2=3\cdot2^{2t}+2^{t+2}+1$, and $\mathcal{Y}^d_t$ has consecutive
coordinates, so its odd leg is $2M_t+1$, the same number.
\end{proof}

\begin{theorem}[Equal-depth splitting pairs at every position]\label{thm:eqdepth}
For every $t\ge2$ there are valid nodes $P\ne Q$ with $N(P)=N(Q)$,
$|\adr(P)|=|\adr(Q)|>t$, equal $A$-nesses at all positions below $t$, and opposite $A$-nesses
at $t$.
\end{theorem}

\begin{proof}[Proof sketch]
For $t\ge3$ take $\mathcal{X}^d_t$ and $\mathcal{Y}^d_t$, whose addresses are the two words
above, of equal length $2t>t$; their second coordinates have valuations exactly $t$ and exactly
$t+1$, so Lemma~\ref{lem:tools}(2) applies. For $t=2$ the pair $(13,8)$ and $(53,52)$ works:
both have odd leg $105$ and depth $5$, with addresses $ABAAA$ and $CACAA$.
\end{proof}

\begin{theorem}[Depth-augmented sealing]\label{thm:depthseal}
For every $t\ge2$ and every $f:\mathbb{N}\times\mathbb{N}\to\{\Ttrue,\Tfalse\}$ the rule
\[
 \ell_t(P)=A \iff f\bigl(N(P),\,|\adr(P)|\bigr)
\]
fails at some valid node of depth greater than $t$. In particular no
$(N\bmod2^k,\text{depth})$ classifier works, for any $k$.
\end{theorem}

\begin{theorem}[Infinitely many equal-depth pairs at position two]
With $C_j=3\cdot2^{j+1}+1$, the words $CA^jCA^2$ and $BA^{\,j+3}$, both of length $j+4$,
evaluate to $(4C_j+1,\ 4C_j)$ and $(2^{j+3}+3,\ 2^{j+3})$; these have the common odd leg
$3\cdot2^{j+4}+9$, equal depth, and split at position $2$. Since the odd legs increase strictly
with $j$, no eventually correct $(N,\text{depth})$ classifier exists at position $2$ either.
\end{theorem}

Exhaustive search over odd $N<10^5$ and all their coprime factorisations produces the smallest
equal-depth witnesses, consistent with the families above:

\begin{center}
\begin{tabular}{cccc}
\toprule
position $t$ & odd leg & nodes & common depth\\
\midrule
$2$ & $57$ & $(29,28)$, $(11,8)$ & $4$\\
$3$ & $105$ & $(13,8)$, $(19,16)$ & $5$\\
$4$ & $833$ & $(33,16)$, $(417,416)$ & $8$\\
$5$ & $2697$ & $(61,32)$, $(451,448)$ & $9$\\
$6$ & $12545$ & $(129,64)$, $(6273,6272)$ & $12$\\
$7$ & $47625$ & $(253,128)$, $(7939,7936)$ & $13$\\
\bottomrule
\end{tabular}
\end{center}

\section{The information-theoretic reading}

Fix a population of nodes and set
$I_k=I\bigl(N\bmod2^k\,;\,([\ell_0=A],[\ell_1=A])\bigr)$. Three structural facts control the
curve. First, by Theorem~\ref{thm:bijection} the pair of $A$-nesses is a function of $N\bmod8$,
so $I_k$ is constant for $k\ge3$. Second, $N$ is odd, so $I_1=0$, and $N\bmod4$ determines only
the first bit, so $I_2<I_3$ unless the second bit is almost surely constant. Third, by
Theorem~\ref{thm:noclass2} and Corollary~\ref{cor:zerovar} adjoining $[\ell_2=A]$ cannot raise
the ceiling.

For the population of all $3^9=19\,683$ nodes at distance $9$ from the root, so that each
address letter is uniform on $\{A,B,C\}$ and independent of the others, one measures in bits:

\begin{center}
\begin{tabular}{lccccccc}
\toprule
modulus $2^k$ & $2$ & $4$ & $8$ & $16$ & $32$ & $64$ & $128$\\
\midrule
$I(N\bmod2^k;\ \ell_0,\ell_1)$ & $0.000$ & $0.918$ & $1.837$ & $1.837$ & $1.837$ & $1.837$ & $1.837$\\
$I(N\bmod2^k;\ \ell_0,\ell_1,\ell_2)$ & $0.000$ & $0.918$ & $1.837$ & $1.837$ & $1.837$ & $1.837$ & $1.837$\\
\bottomrule
\end{tabular}
\end{center}

The saturation value is $2H(1/3)=2\log_23-\frac43\approx1.8366$ bits: exactly two letters'
worth of $A$-ness. The location of the knee, modulus $8$, is population-independent; its height
depends on the sampling measure.

\section{Algorithms}

\emph{Address extraction.} Emit $\lett(m,n)$ and replace $(m,n)$ by $\pi(m,n)$ until the root is
reached; reverse. Each step halves $m$ or $n$, so the cost is $O(\log(m+n))$ operations.

\emph{Prefix prediction from the residue.} From $N$ alone output
$[\ell_0=A]=[N\equiv1\ (4)]$ and $[\ell_1=A]=[N\bmod8\in\{1,3\}]$, in constant time; by
Theorem~\ref{thm:sealall} this is the maximal correct output of any such routine.

\emph{Splitting-pair generator.} For a target $t\ge2$, return the pair of
Definition~\ref{def:bigfam} with $s=t-2$, or the equal-depth pair of
Theorem~\ref{thm:eqdepth}; each call refutes an entire class of candidate classifiers.

\emph{Exhaustive splitting search.} Bucket the valid pairs with $m<X$ by odd leg and report
buckets containing two nodes of depth $>t$ with opposite $A$-nesses at $t$. At $t=2$ this finds
$3\,255$ pairs among $m<300$ and $6\,124$ among $m<400$, the smallest odd leg being $33$.

\section{Discussion}

\subsection{Why exactly two}
The run laws make the address near the leaf a deterministic function of $u_0=\vtwo(p+q)$
together with the size comparisons separating $B$ from $C$. The residue $N\bmod2^k$ sees $u_0$
only through the trichotomy $u_0=1$, $u_0=2$, $u_0\ge3$, whose first two cases pin $\ell_0$ and
$\ell_1$. Finer information would have to be extracted from $N=pq=\bigl(\frac U2\bigr)^2-\bigl(\frac V2\bigr)^2$,
and that quadratic reconstruction destroys the correspondence of higher bits. The splitting
families are the explicit certificates that the loss is total.

\subsection{The which-factor wall}
Nodes with a given odd leg are coprime factorisations of it, so a classifier for a deep address
position would be a factor-discriminating function of $N$, or of $N$ and the depth. All such
classifiers are refuted here, placing the Price address among the sealed residue dials: cheap
descriptions revealing a bounded number of bits and then factor-blind. Theorem~\ref{thm:BC}
exhibits the wall in its purest form, since the $B$/$C$ decision is literally a comparison of
the sizes of the two factors.

\subsection{Two trees, one map}
For the classical Berggren tree the analogous question concerns $3$-adic data, and the seal
there is total from position $0$. The present results complete the corresponding picture for
the Price tree: exactly two visible clicks at the prime $2$, then structural sealing at every
subsequent position, against the odd leg, against every $2$-adic residue, and against the
depth. This suggests that the number of visible clicks is an invariant of a triple tree and its
associated prime, determined by how many bits of the descent invariant survive the nonlinear
reconstruction of the odd leg.

\subsection{Scope}
The negative results concern functions of $N$, or of $(N,\text{depth})$, alone. Given an actual
factorisation of $N$ the node is determined and its whole address is computable in logarithmic
time. Nor are statistical statements precluded: what is precluded is any \emph{correct} rule,
together with any degeneracy of the conditional laws.

\section{Future directions}

\emph{Two-sided adic budget for triple trees.} The visible prefix length appears to be governed
not by the prime itself but by how many bits of the descent invariant survive the nonlinear
reconstruction of the odd leg: zero clicks at $3$ for the Berggren tree, exactly two at $2$ for
the Price tree. Making the number of visible clicks a computable function of the valuation drop
per step, for a general triple tree and prime, is the natural next theorem.

\emph{Beyond residues and depth.} The proofs consume exactly two pieces of cheap data. Which
further cheap statistics---the even leg modulo powers of two, the hypotenuse, the size of $m$,
the number of prime factors of $N$---are still defeated by an equal-statistic splitting family?

\emph{Quantitative density.} The two-parameter family produces splitting odd legs of quadratic
growth; exhaustive search suggests a positive density of odd legs carrying a splitting pair at
position $2$. The true density, and its dependence on $t$, is open.

\emph{Distributions rather than rules.} Since the conditional law of $\ell_t$ given $N\bmod2^k$
is never degenerate for $t\ge2$, one may ask for its limit, and for the rate at which it
approaches the uniform law of the tree.

\emph{The reverse direction.} All statements here read the address from the leaf; reading from
the root is a different filtration, adapted to size rather than to $2$-adic structure, and its
visibility question is untouched.

\appendix
\section{Worked examples}

\emph{Two triangles, one number.} $105=1\cdot105=3\cdot35=5\cdot21=7\cdot15$ gives the four
nodes $(53,52)$, $(19,16)$, $(13,8)$, $(11,4)$ with addresses $CACAA$, $BAAAA$, $ABAAA$,
$CBAA$. Since $105\equiv1\pmod8$, all four read $A$ at positions $0$ and $1$. At position $2$
they already disagree: $(13,8)$ and $(19,16)$ read $A$, $(53,52)$ reads $C$, $(11,4)$ reads
$B$. The two nodes $(13,8)$ and $(19,16)$ agree at positions $0,1,2$ and share the depth $5$,
yet disagree at position $3$.

\emph{The countdown.} For $(41,14)$: $U=82$, $\vtwo(U)=1$, so the leaf letter is $A$, matching
$N=1485\equiv1\pmod4$. Its parent $(34,7)$ has $U=68$, $\vtwo(U)=2$, so its letter is not $A$
and the next $A$ sits one step further up. The address is $ABBABA$.

\emph{A sealing certificate at $t=4$.} $X_2=(593,592)$ and $Y_2=(47,32)$ both have odd leg
$1185$; $\vtwo(592)=4$ exactly and $\vtwo(32)=5$, so their addresses are all-$A$ at positions
$0,1,2,3$ and split at position $4$. Any rule ``$\ell_4=A$ iff $f(1185)$'' is wrong on one of
them.

\end{document}

