    print("\n[2] The B/C split is a SIZE rule, never a congruence")
    bc = b_versus_c(300)
    print(f"    'letter = B  <=>  N = 3 (mod 4) and q < 3p': "
          f"{bc['violations']} violations")
    print(f"    counts among nodes with m < 300:  B: {bc['count_B']}, "
          f"C: {bc['count_C']}")
