"""
The which-factor wall: reading a Pythagorean address from its odd leg, and failing.

A node of the Price tree with odd leg N is exactly a coprime factorisation N = p*q with
0 < p < q, via m = (p+q)/2 and n = (q-p)/2.  This script

  1. lists, for a given odd N, all of its coprime factorisations, the corresponding nodes,
     their addresses, their depths, and their letters at the youngest positions;
  2. verifies that all of them agree at positions 0 and 1 (as the mod-8 dictionary forces)
     and exhibits the positions where they disagree;
  3. runs a *classifier consistency check*: for a target position t and a modulus 2^k, it
     tries to build the best possible rule "letter at position t is A iff N mod 2^k lies in
     S" from the data itself, and reports the residue classes in which the data contradict
     every choice of S.  The contradictions never disappear, however large k is.

Run:  python3 demo2.py
"""

from __future__ import annotations

from collections import defaultdict
from math import gcd
from typing import Dict, Iterator, List, Set, Tuple

Pair = Tuple[int, int]
ROOT: Pair = (2, 1)


def is_valid(p: Pair) -> bool:
    m, n = p
    return 0 < n < m and gcd(m, n) == 1 and (m + n) % 2 == 1


def letter_of(p: Pair) -> str:
    m, n = p
    if n % 2 == 0:
        return "A"
    return "B" if 2 * n < m else "C"


def parent(p: Pair) -> Pair:
    m, n = p
    if n % 2 == 0:
        return (m - n // 2, n // 2)
    if 2 * n < m:
        return (m // 2, m // 2 - n)
    return (m // 2, n - m // 2)


def address(p: Pair) -> str:
    out: List[str] = []
    while p != ROOT:
        out.append(letter_of(p))
        p = parent(p)
    return "".join(reversed(out))


def letter_at(p: Pair, t: int) -> str:
    for _ in range(t):
        p = parent(p)
    return letter_of(p)


def odd_leg(p: Pair) -> int:
    m, n = p
    return m * m - n * n


def nodes_of_odd_leg(N: int) -> List[Pair]:
    """All Price nodes whose odd leg is N: the coprime factorisations N = p*q, p < q."""
    out: List[Pair] = []
    for p in range(1, int(N ** 0.5) + 1):
        if N % p:
            continue
        q = N // p
        if p < q and gcd(p, q) == 1 and (p + q) % 2 == 0:
            node = ((p + q) // 2, (q - p) // 2)
            if is_valid(node):
                out.append(node)
    return sorted(out)


def all_nodes(bound: int) -> Iterator[Pair]:
    for m in range(2, bound):
        for n in range(1, m):
            if is_valid((m, n)):
                yield (m, n)


def classifier_consistency(bound: int, t: int, k: int) -> Dict[str, object]:
    """Try to fit a rule 'position t is A iff N mod 2^k in S' to the observed data."""
    labels: Dict[int, Set[bool]] = defaultdict(set)
    witness: Dict[int, Dict[bool, Pair]] = defaultdict(dict)
    for p in all_nodes(bound):
        if len(address(p)) <= t:
            continue
        r = odd_leg(p) % (2 ** k)
        lab = letter_at(p, t) == "A"
        labels[r].add(lab)
        witness[r].setdefault(lab, p)
    contradictory = sorted(r for r, s in labels.items() if len(s) == 2)
    example = None
    if contradictory:
        r = contradictory[0]
        example = (r, witness[r][True], witness[r][False])
    return {
        "classes_seen": len(labels),
        "contradictory_classes": len(contradictory),
        "example": example,
    }


def main() -> None:
    bar = "=" * 74
    print(bar)
    print("THE WHICH-FACTOR WALL")
    print(bar)

    for N in (105, 1155, 3465):
        print(f"\nOdd leg N = {N}   (N mod 8 = {N % 8})")
        print(f"  {'factorisation':>18} {'node':>16} {'depth':>6} {'address':>26} "
              f"{'pos 0,1,2':>12}")
        rows = []
        for node in nodes_of_odd_leg(N):
            m, n = node
            w = address(node)
            letters = "".join(letter_at(node, t) for t in (0, 1, 2))
            rows.append((node, w, letters))
            print(f"  {f'{m - n} x {m + n}':>18} {str(node):>16} {len(w):>6} {w:>26} "
                  f"{letters:>12}")
        first_two = {(r[2][0] == "A", r[2][1] == "A") for r in rows}
        third = {r[2][2] == "A" for r in rows}
        print(f"  A-ness at positions 0,1 identical across all factorisations: "
              f"{len(first_two) == 1}")
        print(f"  A-ness at position 2 already splits the factorisations:      "
              f"{len(third) == 2}")

    print("\n" + bar)
    print("CLASSIFIER CONSISTENCY: can any residue rule read position t?")
    print(bar)
    print(f"\n  {'t':>3} {'k':>3} {'modulus':>9} {'classes seen':>13} "
          f"{'contradictory':>14}")
    for t in (0, 1, 2, 3):
        for k in (3, 5, 7, 9):
            res = classifier_consistency(260, t, k)
            print(f"  {t:>3} {k:>3} {2 ** k:>9} {res['classes_seen']:>13} "
                  f"{res['contradictory_classes']:>14}")
    print("\n  Positions 0 and 1: zero contradictory classes at every modulus — the rule")
    print("  exists and is the mod-8 dictionary.  Positions 2 and 3: contradictions in")
    print("  essentially every class, and refining the modulus does not remove them.")

    res = classifier_consistency(260, 2, 9)
    if res["example"]:
        r, pT, pF = res["example"]  # type: ignore[misc]
        print(f"\n  A concrete contradiction modulo 512: residue {r}")
        print(f"    {pT} has odd leg {odd_leg(pT)}, address {address(pT)}, "
              f"letter at 2 = {letter_at(pT, 2)}")
        print(f"    {pF} has odd leg {odd_leg(pF)}, address {address(pF)}, "
              f"letter at 2 = {letter_at(pF, 2)}")

    print("\n" + bar)
    print("Two clicks are readable; the third letter is not a function of N at all.")
    print(bar)


if __name__ == "__main__":
    main()

