from math import gcd
from typing import List, Tuple

Pair = Tuple[int, int]
ROOT: Pair = (2, 1)


def is_valid(node: Pair) -> bool:
    """A Euclid parameter pair: m > n > 0, coprime, of opposite parity."""
    m, n = node
    return 0 < n < m and gcd(m, n) == 1 and (m + n) % 2 == 1


def letter_of(node: Pair) -> str:
    """The move that produced this node: A if n is even, else B or C by size."""
    m, n = node
    if n % 2 == 0:
        return "A"
    return "B" if 2 * n < m else "C"


def parent(node: Pair) -> Pair:
    """Invert the move that produced the node (one ascent step)."""
    m, n = node
    if n % 2 == 0:                 # A halved V = q - p = 2n
        return (m - n // 2, n // 2)
    if 2 * n < m:                  # B halved U = p + q = 2m
        return (m // 2, m // 2 - n)
    return (m // 2, n - m // 2)    # C halved U as well


def address(node: Pair) -> str:
    """The unique word over {A,B,C} spelling the path from the root to the node."""
    if not is_valid(node):
        raise ValueError(f"{node} is not a Euclid pair")
    letters: List[str] = []
    while node != ROOT:
        letters.append(letter_of(node))
        node = parent(node)
    return "".join(reversed(letters))


def letter_at(node: Pair, t: int) -> str:
    """The letter at position t counted backwards from the leaf (t = 0 is the last)."""
    for _ in range(t):
        node = parent(node)
    return letter_of(node)


def depth(node: Pair) -> int:
    """Distance from the root, i.e. the length of the address."""
    return len(address(node))

