function AUDIT_RESIDUE_CLASSIFIER(bound, t, k):
    labels <- empty map from residue to set of booleans
    witness <- empty map from residue to map from boolean to node
    for each valid node (m, n) with m < bound:
        if depth(m, n) <= t: continue
        r <- (m^2 - n^2) mod 2^k
        b <- (LETTER_AT(m, n, t) = 'A')
        labels[r] <- labels[r] union {b}
        record witness[r][b] if not already present
    bad <- { r : |labels[r]| = 2 }
    return (classes_seen = |labels|,
            contradictory = |bad|,
            fittable = (bad is empty),
            witness = a pair of nodes from the first bad class)

