from collections import defaultdict
from math import gcd
from typing import Dict, Iterator, List, Set, Tuple

Pair = Tuple[int, int]
ROOT: Pair = (2, 1)


def _letter_of(node: Pair) -> str:
    m, n = node
    if n % 2 == 0:
        return "A"
    return "B" if 2 * n < m else "C"


def _parent(node: Pair) -> Pair:
    m, n = node
    if n % 2 == 0:
        return (m - n // 2, n // 2)
    if 2 * n < m:
        return (m // 2, m // 2 - n)
    return (m // 2, n - m // 2)


def _depth(node: Pair) -> int:
    d = 0
    while node != ROOT:
        node = _parent(node)
        d += 1
    return d


def _letter_at(node: Pair, t: int) -> str:
    for _ in range(t):
        node = _parent(node)
    return _letter_of(node)


def _nodes(bound: int) -> Iterator[Pair]:
    for m in range(2, bound):
        for n in range(1, m):
            if 0 < n < m and gcd(m, n) == 1 and (m + n) % 2 == 1:
                yield (m, n)


def audit_residue_classifier(bound: int, t: int, k: int) -> Dict[str, object]:
    """Ask whether ANY rule 'position t is A iff N mod 2^k in S' can fit the data.

    A residue class is *contradictory* if it contains two nodes with opposite
    A-nesses at position t; a single contradictory class refutes every choice of S.
    Returns the number of classes observed, the number of contradictory ones, and a
    witness pair for the first contradiction found.
    """
    labels: Dict[int, Set[bool]] = defaultdict(set)
    witness: Dict[int, Dict[bool, Pair]] = defaultdict(dict)
    for node in _nodes(bound):
        if _depth(node) <= t:
            continue
        m, n = node
        r = (m * m - n * n) % (2 ** k)
        lab = _letter_at(node, t) == "A"
        labels[r].add(lab)
        witness[r].setdefault(lab, node)
    bad: List[int] = sorted(r for r, s in labels.items() if len(s) == 2)
    example = None
    if bad:
        r = bad[0]
        example = (r, witness[r][True], witness[r][False])
    return {"classes_seen": len(labels),
            "contradictory_classes": len(bad),
            "fittable": not bad,
            "witness": example}

